PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?ps ?loc ?t ?lbl WHERE {
  ?ps a brick:Electric_Power_Sensor .
  OPTIONAL { ?ps brick:hasLocation ?loc . }
  OPTIONAL { ?ps brick:hasTimeseriesId ?ts . ?ts a ref:TimeseriesReference . }
  OPTIONAL { ?ps rdfs:label ?lbl . }
  OPTIONAL { ?ps brick:ifcName ?t . }
} LIMIT 100

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?ps ?loc ?tsid ?lbl WHERE {
  ?ps a brick:Electric_Power_Sensor .
  ?loc ?p ?o .
  { ?ps rdfs:label ?lbl } UNION { ?lbl ?x ?y }
} LIMIT 100

PREFIX brick: <https://brickschema.org/schema/Brick#>
PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p ?tsid WHERE {
  ?p ref:hasTimeseriesId ?tsid .
  FILTER(str(?tsid) LIKE "%Zone%")
} LIMIT 30

PREFIX ref: <https://brickschema.org/schema/Brick/ref#>
SELECT ?p ?tsid WHERE {
  ?p ref:hasTimeseriesId ?tsid .
} LIMIT 300

